const P={
datastream:{name:'Datastream',area:'接入 · 数据库变化',one:'把业务数据库里“新增、修改、删除”的变化持续送到下游，而不用反复整库导出。',problem:'业务数据库首先要保证订单、库存、客户服务正常。若每天全量复制，不但慢，也可能给生产系统增加压力；而业务方又希望尽快看见变化。Datastream 为这种“只拿变化”的同步方式设计。',fit:'它适合持续复制数据库或 SaaS 应用数据的变化；它不是用来搬大批文件的服务。',components:[['连接配置','Connection profile','保存如何连到来源或目标的信息，例如地址、认证和网络设置。可以把它理解为“通讯录和通行证”。'],['数据流','Stream','一条正在运行的复制任务：从哪个来源取哪些对象，送到哪里。'],['初始补数','Backfill','开始时把已有历史数据复制一次；之后再持续接收变化。'],['变化捕获','CDC（Change Data Capture）','只读取后续的新增、修改、删除事件，而不是每次重读整张表。']],steps:[['准备来源','确认来源数据库允许读取变更，并配置网络和最小权限。'],['建立连接','分别创建来源与目标的 connection profile。'],['定义数据流','选择要复制的 schema/table、目标和初始补数策略。'],['启动与监控','启动 stream，检查补数完成和持续复制状态。']],specs:[['主要来源','官方文档列出 Oracle、MySQL、SQL Server、PostgreSQL、MongoDB、Spanner、Salesforce 等；不同来源的版本、权限与配置要求不同。'],['常见目标','可写入 Cloud Storage；也提供与 Dataflow 模板的集成，构建到更多目标的后续处理。支持范围以官方“sources and destinations”列表为准。'],['运行方式','无服务器：不需要自己部署 CDC 集群，但仍需要为来源端网络、账号和日志/变更机制做准备。'],['计费关注点','按处理的数据量等用量计费；初始补数、CDC 数据量及目标端的 Dataflow、存储或数仓服务可能分别收费。']],docs:'https://cloud.google.com/datastream/docs',price:'https://cloud.google.com/datastream/pricing'},
transfer:{name:'Storage Transfer Service',area:'接入 · 文件与对象',one:'把本地、其他云或对象存储里的大量文件，可靠地搬到目标位置，并可按计划重复同步。',problem:'历史数据往往散在数据中心文件夹、HDFS、S3、Azure Blob 或另一个 Cloud Storage bucket。手动拷贝难以重试、难以审计，也很难在数据量很大时稳定完成。',fit:'它解决“文件/对象怎么搬”；不读取数据库行级变更，数据库持续同步应考虑 Datastream。',components:[['传输任务','Transfer job','描述从哪里到哪里、什么时候运行、复制/删除规则是什么。'],['代理池','Agent pool','当来源是本地文件系统等私有网络时，运行在客户网络内的 agent 集合负责传输。'],['过滤与同步规则','Include / exclude / schedule','用前缀、修改时间和运行计划决定哪些对象要传。'],['运行记录','Operations','每次执行的进度、成功和失败信息，方便排查与重试。']],steps:[['确定来源与目标','先识别数据在对象存储、HDFS、文件系统或 URL 列表中。'],['选择模式','云到云通常不需 agent；需要访问私网文件系统时配置 agent pool。'],['创建传输任务','设置路径、筛选规则、运行一次或按计划运行。'],['观察与复核','查看执行结果，确认对象数量、错误和后续增量同步。']],specs:[['支持的路径','官方概览列出 Amazon S3、Azure Blob、Cloud Storage、HDFS、本地文件系统与公开 URL 等；具体组合以支持矩阵为准。'],['规模定位','官方说明服务针对超过 1 TiB 的传输优化；小规模操作也可使用其他工具。'],['传输方式','可使用 Google 托管传输，也可通过自托管 agent 控制私网访问和网络路径。'],['计费关注点','不同来源/模式的服务费不同，另需考虑目标 Cloud Storage、网络和源云厂商费用。']],docs:'https://cloud.google.com/storage-transfer/docs/overview',price:'https://cloud.google.com/storage-transfer-service#pricing'},
pubsub:{name:'Pub/Sub',area:'接入 · 业务事件',one:'让“发生了一件事”的系统，把消息可靠地交给多个下游，而不必彼此等待。',problem:'支付完成、客户点击、设备上报等事件会同时被风控、通知、运营和分析使用。如果每个系统直接互调，任何一个接收方故障或变慢都可能拖住生产方。Pub/Sub 用中间消息层把双方拆开。',fit:'适合实时业务事件、日志和流式接入；它负责传递，不负责复杂计算和字段加工。',components:[['主题','Topic','消息发布到的“公共频道”。生产者只管发到这里。'],['订阅','Subscription','某个下游如何接收 topic 的消息；同一 topic 可以有多个独立订阅。'],['发布者和订阅者','Publisher / subscriber','发送消息的应用与处理消息的应用。它们不必同时在线。'],['消息约束','Schema / ordering / delivery','可选地约束消息格式、保证同一 ordering key 的顺序，或配置 exactly-once 交付。']],steps:[['定义事件','先用业务语言约定事件：例如“订单已支付”里必须包含哪些字段。'],['创建 topic','让产生事件的系统向 topic 发布消息。'],['为下游建订阅','每个消费者拥有自己的 subscription，不互相抢进度。'],['处理或落地','下游可直接处理，或交给 Dataflow 再清洗、汇总和写出。']],specs:[['核心模式','发布/订阅；一个 topic 可以有多个 subscription。生产者与消费者独立伸缩。'],['交付方式','subscription 支持 pull、push 与 export 等方式；默认至少一次交付，另有 exactly-once 与顺序交付等可选能力，适用条件请查官方文档。'],['延迟与弹性','官方概览称其为异步、可扩展服务，典型延迟量级约 100 毫秒；实际端到端延迟还取决于客户端和下游处理。'],['计费关注点','主要看发布、订阅/传递字节量、消息保留与跨区域传输。']],docs:'https://cloud.google.com/pubsub/docs/overview',price:'https://cloud.google.com/pubsub/pricing'},
kafka:{name:'Managed Service for Apache Kafka',area:'接入 · Kafka 事件流',one:'保留 Kafka 的应用与开发方式，同时把集群的底层维护交给 Google Cloud。',problem:'团队已经有 Kafka producer、consumer、topic 和连接器，不希望为了上云重写所有应用；但自行维护 broker、存储、补丁和可用区又是一项长期运维工作。',fit:'适合既有 Kafka 资产、跨环境一致体验或事件日志模式；若追求无服务器和最少容量管理，官方建议同时评估 Pub/Sub。',components:[['集群与 broker','Cluster / brokers','Kafka 的运行环境与处理节点。创建集群时按 vCPU 和内存指定容量，服务据此配置 broker。'],['主题与分区','Topics / partitions','事件按 topic 分类、按 partition 并行和保留顺序；这是 Kafka 应用的核心模型。'],['Kafka Connect','Connect clusters','使用连接器把 Kafka 与其他系统连接，用于集成、迁移和复制。'],['Schema Registry','Schema registry','共享消息结构定义，帮助生产者和消费者对字段格式达成一致；该能力的发布阶段应以官方页面为准。']],steps:[['盘点现有 Kafka','确认现有客户端版本、topic、认证、网络和连接器依赖。'],['规划集群容量','按吞吐、保留期和副本需求确定 vCPU、内存与存储。'],['配置私网访问与认证','选择 VPC、SASL/IAM 或 mTLS 等官方支持的模式。'],['迁移与连接','让现有客户端连到新集群，按需配置 Kafka Connect。']],specs:[['可移植性','运行开源 Apache Kafka，官方强调可与已有 Kafka 应用兼容；仍应逐项核对客户端和 broker 版本兼容性。'],['高可用结构','官方概览说明区域集群采用跨三个 zone 的 rack-aware 配置；该设计保护单个 zone 或 broker 故障，不等同于跨区域灾备。'],['存储与保留','提供分层存储；topic 的 retention 由使用方设置，直接影响成本和可回放范围。'],['容量与计费','需配置 vCPU、内存，服务自动配置 broker；费用与集群计算/内存、存储、网络和 Connect 等有关。']],docs:'https://cloud.google.com/managed-service-for-apache-kafka/docs/overview',price:'https://cloud.google.com/managed-service-for-apache-kafka/pricing'},
dataflow:{name:'Dataflow',area:'处理 · 批处理与实时流',one:'把不断到来的事件或一批历史数据，自动并行地清洗、关联、计算后写到目标系统。',problem:'把数据“送到”某处还不够：通常要过滤脏数据、统一格式、关联客户信息、按时间汇总、计算指标。数据量波动大时，自己管理一组计算机器很麻烦。',fit:'适合大规模 ETL、实时分析、日志/传感器处理、窗口聚合和数据富化。不是低代码集成门户；若更需要拖拽式连接器，可先看 Cloud Data Fusion。',components:[['处理流程','Pipeline','您定义的数据从哪里读、经过哪些转换、写到哪里；这是逻辑，而不是一台机器。'],['执行任务','Job','把 pipeline 提交到 Dataflow 后产生的实际运行实例，可监控每个阶段。'],['Apache Beam','SDK / programming model','定义 pipeline 的开源编程模型；Dataflow 是其托管执行环境。'],['模板与 Job Builder','Templates / Job Builder','不想从零写代码时，可运行预建模板或用控制台的可视化方式做较简单的数据移动。']],steps:[['描述输入和结果','明确来源、目标、转换规则及实时/批量时效要求。'],['选构建方式','简单移动选模板或 Job Builder；复杂逻辑用 Apache Beam 的 Java、Python 或 Go SDK。'],['运行 job','提交 job，Dataflow 分配 worker 并按负载自动扩缩。'],['监控和优化','使用 job graph、指标、日志、数据新鲜度和告警定位瓶颈。']],specs:[['运行模式','同一服务支持 batch 与 streaming；streaming 面向持续到达的数据，batch 面向有限输入。'],['开发选择','官方支持 Apache Beam SDK（Java、Python、Go）、模板、Job Builder 与 Notebook 等途径；不同方式的能力范围不同。'],['处理语义','官方概览称流式管道默认提供 exactly-once 处理；也可选择容忍重复的 at-least-once 模式以改善成本或延迟。'],['伸缩与可观测性','服务管理 worker 池并自动扩缩；控制台提供 stages、数据新鲜度、资源、日志和成本估算等观测信息。']],docs:'https://cloud.google.com/dataflow/docs/overview',price:'https://cloud.google.com/dataflow/pricing'},
spark:{name:'Managed Service for Apache Spark',area:'处理 · Spark/Hadoop',one:'在不自己搭建整套集群的前提下，运行既有或新的 Spark/Hadoop 数据处理工作。',problem:'很多组织已经积累了 PySpark、Spark SQL、Hive 或 Hadoop 作业。迁移到云端时，最现实的诉求常常是继续运行这些资产，同时减少集群创建、修补、监控和关停的工作。',fit:'适合已有 Spark/Hadoop 代码、需要开源生态兼容性或受控集群。Dataproc 与 Serverless for Apache Spark 已被统一到此产品。',components:[['无服务器作业','Serverless','把 Spark 作业直接提交给服务；不需要自己预先创建和维护集群，按作业执行时的资源计费。'],['托管集群','Clusters','当需要更多基础设施控制、持久集群或多种 OSS 工具时使用；服务负责部分集群生命周期管理。'],['作业驱动','Job driver','接收并启动 Spark 等作业的组件；使用者提交的是 job，而不是手动登陆每台机器执行。'],['镜像与依赖','Images / dependencies','用于规定 Spark、Hadoop 和额外库的运行环境；需按作业兼容性管理。']],steps:[['梳理现有作业','确认语言、依赖、数据访问、调度方式和是否需要交互式/持久环境。'],['选部署模式','新管道或临时分析通常偏无服务器；需要细粒度控制、迁移复杂资产时考虑集群。'],['提交与配置','指定主程序、参数、身份与数据位置，提交 Spark batch 或创建集群后运行。'],['运行观察','查看 job 结果、日志、资源和成本；将集群在不用时缩到零或关闭。']],specs:[['两种部署','官方文档对比 serverless 与 clusters：前者是 jobs-as-a-service，后者是 clusters-as-a-service，控制程度和计费方式不同。'],['生态范围','官方文档列出 Apache Spark、Hadoop、Hive、Pig 等；实际版本取决于所选 image/version。'],['基础设施控制','serverless 不提供 VM 访问，clusters 提供更多配置与 SSH 等控制能力；需按工作负载选择。'],['计费关注点','serverless 以实际 job 运行资源（例如 DCU、shuffle、加速器）为主；clusters 还涉及底层 VM、磁盘和管理费。']],docs:'https://cloud.google.com/products/managed-service-for-apache-spark',price:'https://cloud.google.com/products/managed-service-for-apache-spark/pricing'},
fusion:{name:'Cloud Data Fusion',area:'处理 · 可视化集成',one:'用拖拽和现成连接器，把“从哪里取、怎么整理、送到哪里”拼成可运行的数据流程。',problem:'当来源系统多、格式杂、团队里不全是编程人员时，每条管道都从代码开始会拖慢交付。Cloud Data Fusion 把常见的连接、转换、运行和管理放到一个可视化工作区。',fit:'适合低代码/可视化数据集成与大量连接器场景；若有非常复杂的流式状态或自定义计算，Dataflow 的代码模型更适合。',components:[['实例与命名空间','Instance / namespace','实例是服务部署；namespace 在一个实例内隔离项目的数据与配置。'],['Studio 与 pipeline','Studio / pipeline','Studio 是设计界面；pipeline 是由 source、transform、sink 组成的有向流程。'],['插件','Plugins','已安装或从 Hub 获得的连接器与转换节点，例如 JDBC 读取、字段转换、写入目标。'],['计算配置','Compute profile','说明一个 pipeline 在哪里、用多少资源运行；可以让服务建立临时 Spark 环境。']],steps:[['创建实例','选择 edition、区域、网络与访问控制，进入 Studio。'],['连接和预览','拖入 source，选插件、账号和字段；先用小样本预览转换结果。'],['组合并测试','添加 transform、sink 和错误处理，保存/部署 pipeline。'],['运行与编排','按计划运行，或由上游 pipeline 触发；也可以由 Airflow 统一编排。']],specs:[['开发方式','可视化 DAG；每个节点对应来源、转换、汇聚、目标、告警或动作插件。'],['执行环境','官方概览说明可自动创建临时 Managed Service for Apache Spark 集群，也可指向受控的既有集群。'],['工作负载','官方说明 pipeline 可用于 batch 和 real-time；具体插件和执行模式决定可用能力。'],['计费关注点','实例开发时间和执行计算分开计费；执行时使用的 Spark、存储、网络等资源另计。']],docs:'https://cloud.google.com/data-fusion/docs/concepts/overview',price:'https://cloud.google.com/data-fusion/pricing'},
airflow:{name:'Managed Service for Apache Airflow',area:'运营 · 流程编排',one:'把多个数据任务按正确顺序自动触发、失败重试并留下可查看的运行记录。',problem:'数据流程往往不是一个任务：先提取，再处理，再检查质量，最后发布。靠人记顺序和盯结果，迟早会漏跑或无法解释为什么今天的数据没出来。',fit:'适合有依赖关系的 ETL/ELT、跨云或跨系统批处理编排。它协调工作，不替 Dataflow 或 Spark 执行大规模计算。',components:[['环境','Environment','托管的 Airflow 部署，包含调度、worker、Web UI、元数据和相关基础设施。'],['DAG','Directed Acyclic Graph','用 Python 表达“哪些任务、什么顺序、什么依赖”；DAG 是工作流蓝图。'],['任务与 operator','Tasks / operators','任务是一个步骤；operator 是调用 Dataflow、Spark、存储等系统的预建方式。'],['调度与 sensor','Schedule / sensors','定时运行，或等待文件、消息、上游任务等条件满足再继续。']],steps:[['画出业务顺序','先把“先做什么、失败怎么办、何时发布”写成流程。'],['用 Python 写 DAG','将每一步定义成 task，并声明依赖、重试和运行时间。'],['放入环境','把 DAG 上传到环境关联的存储位置，在 Airflow UI 看到它。'],['观察和处置','查看每个 task 的状态和日志；失败时重试、定位或暂停后续任务。']],specs:[['表达方式','以 Python DAG 表示数据驱动工作流；官方明确将其定位于特别适合 ETL/ELT 的编排。'],['执行特性','适合可以容忍任务之间数秒延迟的 batch 工作；不是低延迟微服务编排引擎。'],['集成范围','Airflow operators/sensors 可调用 Google Cloud 与其他系统；官方对比页提及仅 Google Cloud 就有 150+ operators。'],['底层组成','官方概览说明环境基于 GKE，含 scheduler、triggerer、worker、Web server、Airflow metadata database 与环境 bucket。']],docs:'https://cloud.google.com/composer/docs/composer-3/composer-overview',price:'https://cloud.google.com/composer/pricing'},
dataform:{name:'Dataform',area:'运营 · SQL 转换开发',one:'把一堆 SQL 变成有依赖、有版本、有测试、能按顺序发布的数据转换项目。',problem:'数据已进入 BigQuery 后，团队仍会面临 SQL 散落、表依赖不清、改动影响未知、口径没有文档、数据异常发现太晚的问题。Dataform 把 SQL 变成可工程化管理的 ELT 工作流。',fit:'仅用于 BigQuery 内的数据转换与建模；不是从外部采集数据的通用 ETL，也不是独立数据仓。',components:[['仓库与工作区','Repository / workspace','repository 存放 SQLX、配置和文档；workspace 是个人/分支式开发空间。'],['Dataform core / SQLX','SQL 扩展语言','在 SQL 基础上声明表类型、依赖、配置与断言；编译后成为 BigQuery SQL。'],['发布与工作流配置','Release / workflow config','把某个代码版本固定为可发布版本，并定义何时运行、运行哪些内容。'],['断言','Assertions','对源表或结果表运行检查，用于发现空值、重复、条件不满足等问题。']],steps:[['定义模型','声明原始数据来源，写出目标表、视图或增量表的转换逻辑。'],['看依赖图并测试','在 workspace 编译，检查依赖、预览 SQL 和运行 assertions。'],['接入版本控制','使用 Git 协作、评审和发布代码变更。'],['安排运行','建立 release 与 workflow configuration，让 BigQuery 按依赖顺序执行。']],specs:[['运行目标','Dataform 将代码编译为 Standard SQL，并在 BigQuery 中按依赖图执行。'],['支持的资产','可管理 tables、views、materialized views 与 incremental tables；具体 BigQuery 能力受其自身限制。'],['工程能力','支持 Git、依赖图、JavaScript 复用、文档和 assertions；编译会发现缺失或循环依赖。'],['计费关注点','官方价格页说明 Dataform 服务本身免费；BigQuery 查询、Cloud Logging 及可能用到的编排服务按各自价格计费。']],docs:'https://cloud.google.com/dataform/docs/overview',price:'https://cloud.google.com/dataform/pricing'},
catalog:{name:'Knowledge Catalog',area:'治理 · 资产、质量与血缘',one:'让团队知道每份数据是什么、该不该信、谁负责，以及它从哪里来到哪里去。',problem:'当不同团队各有表和指标，常见问题不是“没有数据”，而是“找不到、看不懂、不敢用”。原 Dataplex Universal Catalog 已更名为 Knowledge Catalog，帮助把技术元数据和业务上下文汇集起来。',fit:'适合数据发现、术语口径、血缘、质量与 AI 所需业务上下文；它不存放或计算业务数据本身。',components:[['资产条目','Entries / assets','一个可被发现的数据资产及其技术结构、描述和相关信息。'],['方面','Aspects','可扩展的元数据块，用于为资产补充业务、技术或运营上下文。'],['业务术语表','Business glossaries','把“GMV”“活跃客户”等组织术语标准化，避免同名不同义。'],['扫描与血缘','Data quality / profile / lineage','自动检查质量、分析数据特征，或展示上下游关系。']],steps:[['选核心资产','先从常被问、影响业务最大的表和指标开始。'],['补上业务语境','写清名称、定义、负责人、敏感性、更新频率和使用规则。'],['建立自动检查','对关键表定义质量规则，设置监控和告警。'],['让团队检索与复用','把搜索、术语表和血缘纳入数据交付和评审。']],specs:[['名称变化','Dataplex Universal Catalog 现为 Knowledge Catalog；官方说明既有 Dataplex API、client libraries、gcloud dataplex 命令与配置仍可继续使用。'],['元数据范围','可自动发现并索引技术结构、业务上下文、质量指标与关系；支持搜索、术语表、质量、剖析和血缘等能力。'],['质量扫描','官方说明可对 BigQuery 与 Iceberg REST Catalog 表定义质量规则，并用新鲜度、完整性、有效性、一致性、唯一性等维度报告结果。'],['计费关注点','官方价格页仍以 Dataplex SKU 命名；处理、元数据存储和关联服务会影响实际费用。']],docs:'https://cloud.google.com/dataplex/docs/introduction',price:'https://cloud.google.com/products/knowledge-catalog/pricing'},
metastore:{name:'Dataproc Metastore',area:'治理 · 数据湖技术目录',one:'让 Spark、Hive、Presto 等计算工具对同一批文件使用同一份“表结构和分区说明书”。',problem:'数据湖里的文件本身不会自动告诉计算引擎：哪些文件是一张表、每列叫什么、按什么日期分区、统计信息是什么。多个临时集群各自维护一份定义，会造成结果和性能不一致。',fit:'适合使用 Hive/Spark/Presto 等开源引擎管理数据湖技术元数据。业务口径和数据发现则更偏向 Knowledge Catalog。',components:[['Metastore 服务','Service','一套托管 Hive Metastore，保存 schema、分区和列统计等元数据。'],['数据库和表','Databases / tables','技术上的逻辑组织方式，把文件位置映射成可查询的表。'],['元数据导入','Metadata import','从既有 Hive Metastore 等来源迁移元数据。'],['处理引擎连接','Engine integration','Spark、Hive、Presto 等连接此服务，共享同一份表定义。']],steps:[['梳理现有表定义','确定现有 Hive Metastore 或数据湖中的数据库、表、分区和访问方式。'],['创建服务','选择服务版本、区域与高可用配置。'],['导入或建立元数据','迁移已有 metadata，或让引擎创建新的数据库和表。'],['将引擎指向服务','配置 Spark/Hive/Presto 等使用同一个 metastore 并验证查询。']],specs:[['标准与兼容','是托管 Apache Hive Metastore（HMS）；官方列出 Apache Hive、Apache Spark 与 Presto 等 OSS 引擎的互操作。'],['存储的内容','管理 schema、partitions、column statistics 等技术元数据，不替代实际数据文件或业务目录。'],['版本与可用性','可选择 Dataproc Metastore 1 或 2；官方说明 2 提供横向扩缩能力，详细特性和区域可用性应查官方版本文档。'],['运行特性','官方称服务高可用、自动修复、无服务器；支持自动备份、监控和导入。']],docs:'https://cloud.google.com/dataproc-metastore/docs/overview',price:'https://cloud.google.com/dataproc-metastore/pricing'}
};
const id=new URLSearchParams(location.search).get('service');const x=P[id]||P.dataflow;
document.title=`${x.name}｜数据管道怎么选`;
const list=(arr,fn)=>arr.map(fn).join('');
document.querySelector('#app').innerHTML=`<div class="page"><p class="crumb">数据管道怎么选 / ${x.area}</p><section class="hero"><span class="tag">${x.area}</span><h1>${x.name}</h1><p>${x.one}</p></section><section class="quick"><div><strong>用一句话说</strong><span>${x.one}</span></div><div><strong>它适合什么</strong><span>${x.fit}</span></div></section><section class="section"><h2>1. 它为什么会被设计出来？</h2><p class="intro">先讲业务问题，不要求读者了解任何产品名。</p><div class="problem-box"><h3>它要解决的困扰</h3><p>${x.problem}</p></div></section><section class="section"><h2>2. 它由什么组成？怎么使用？</h2><p class="intro">左边是正式产品术语；右边先解释它在实际工作中扮演的角色。</p><div class="component-grid">${list(x.components,c=>`<article class="component"><h3>${c[0]}<small>${c[1]}</small></h3><p>${c[2]}</p></article>`)}</div><h2 style="margin-top:30px;font-size:1.35rem">一个典型的使用过程</h2><div class="use-steps">${list(x.steps,(s,i)=>`<article class="use-step"><b>${i+1}</b><h3>${s[0]}</h3><p>${s[1]}</p></article>`)}</div></section><section class="section"><h2>3. 规格、模式与边界</h2><p class="intro">这里列出影响选型、实施和成本的主要技术参数；精确配额、区域与版本请以官方页面为准。</p><dl class="specs">${list(x.specs,s=>`<dt>${s[0]}</dt><dd>${s[1]}</dd>`)}</dl><p class="callout"><strong>实施提醒：</strong>选中产品不等于项目完成。还需要落实数据来源的权限与网络、数据目标、运行监控、成本归属和业务验收标准。</p><div class="links"><a href="${x.docs}" target="_blank" rel="noopener">查看官方文档</a><a href="${x.price}" target="_blank" rel="noopener">查看官方定价</a></div></section></div>`;
